#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct ApplicationSearchProgress {
    pub request_id: String,
    pub sequence: u64,
    pub stage: ApplicationSearchProgressStage,
    #[serde(default)]
    pub provider_request_count: Option<u64>,
    #[serde(default)]
    pub raw_fetched_count: Option<u64>,
    #[serde(default)]
    pub mapped_count: Option<u64>,
    #[serde(default)]
    pub exact_matched_count: Option<u64>,
    #[serde(default)]
    pub admitted_count: Option<u64>,
    #[serde(default)]
    pub requested_limit: Option<u64>,
    #[serde(default)]
    pub remote_total: Option<u64>,
    #[serde(default)]
    pub batch_id: Option<String>,
    #[serde(default)]
    pub loaded_count: Option<u64>,
    pub elapsed_ms: u64,
    pub message: String,
    pub terminal: bool,
}

impl ApplicationSearchProgress {
    pub fn validate(&self) -> Result<(), String> {
        if self.request_id.chars().count() < 1 {
            return Err("request_id is too short".to_string());
        }
        if self.request_id.chars().count() > 128 {
            return Err("request_id is too long".to_string());
        }
        if self.sequence < 1 as _ {
            return Err("sequence must be >= 1".to_string());
        }
        if let Some(value) = &self.provider_request_count {
            if *value < 0 as _ {
                return Err("provider_request_count must be >= 0".to_string());
            }
        }
        if let Some(value) = &self.raw_fetched_count {
            if *value < 0 as _ {
                return Err("raw_fetched_count must be >= 0".to_string());
            }
        }
        if let Some(value) = &self.mapped_count {
            if *value < 0 as _ {
                return Err("mapped_count must be >= 0".to_string());
            }
        }
        if let Some(value) = &self.exact_matched_count {
            if *value < 0 as _ {
                return Err("exact_matched_count must be >= 0".to_string());
            }
        }
        if let Some(value) = &self.admitted_count {
            if *value < 0 as _ {
                return Err("admitted_count must be >= 0".to_string());
            }
        }
        if let Some(value) = &self.requested_limit {
            if *value < 1 as _ {
                return Err("requested_limit must be >= 1".to_string());
            }
            if *value > 10000 as _ {
                return Err("requested_limit must be <= 10000".to_string());
            }
        }
        if let Some(value) = &self.remote_total {
            if *value < 0 as _ {
                return Err("remote_total must be >= 0".to_string());
            }
        }
        if let Some(value) = &self.batch_id {
            if value.chars().count() < 1 {
                return Err("batch_id is too short".to_string());
            }
            if value.chars().count() > 128 {
                return Err("batch_id is too long".to_string());
            }
        }
        if let Some(value) = &self.loaded_count {
            if *value < 0 as _ {
                return Err("loaded_count must be >= 0".to_string());
            }
        }
        if self.elapsed_ms < 0 as _ {
            return Err("elapsed_ms must be >= 0".to_string());
        }
        if self.message.chars().count() < 1 {
            return Err("message is too short".to_string());
        }
        if self.message.chars().count() > 160 {
            return Err("message is too long".to_string());
        }
        let terminal_stage = matches!(
            self.stage,
            ApplicationSearchProgressStage::Completed
                | ApplicationSearchProgressStage::Failed
                | ApplicationSearchProgressStage::Cancelled
        );
        if self.terminal != terminal_stage {
            return Err("terminal must match the application progress stage".to_string());
        }
        for (lower, upper, message) in [
            (
                self.mapped_count,
                self.raw_fetched_count,
                "mapped_count must not exceed raw_fetched_count",
            ),
            (
                self.exact_matched_count,
                self.mapped_count,
                "exact_matched_count must not exceed mapped_count",
            ),
            (
                self.admitted_count,
                self.exact_matched_count,
                "admitted_count must not exceed exact_matched_count",
            ),
            (
                self.admitted_count,
                self.requested_limit,
                "admitted_count must not exceed requested_limit",
            ),
        ] {
            if matches!((lower, upper), (Some(lower), Some(upper)) if lower > upper) {
                return Err(message.to_string());
            }
        }
        Ok(())
    }
}

