#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct CatalogSearchStats {
    pub requested_limit: Option<u64>,
    #[serde(default)]
    pub matched_count: Option<u64>,
    pub request_count: u64,
    pub transport_part_count: u64,
    pub fetched_record_count: u64,
    pub mapped_record_count: u64,
    pub profile_filtered_record_count: u64,
    pub exact_duplicate_record_count: u64,
    pub unique_provider_product_count: u64,
    pub exact_matched_count: u64,
    pub returned_count: u64,
    pub remote_exhausted: bool,
    pub working_set_satisfied: bool,
    pub elapsed_ms: u64,
    pub truncated: bool,
}

impl CatalogSearchStats {
    pub fn validate(&self) -> Result<(), String> {
        if let Some(value) = &self.requested_limit {
            if *value < 1 as _ {
                return Err("requested_limit must be >= 1".to_string());
            }
        }
        if let Some(value) = &self.matched_count {
            if *value < 0 as _ {
                return Err("matched_count must be >= 0".to_string());
            }
        }
        if self.request_count < 0 as _ {
            return Err("request_count must be >= 0".to_string());
        }
        if self.transport_part_count < 0 as _ {
            return Err("transport_part_count must be >= 0".to_string());
        }
        if self.fetched_record_count < 0 as _ {
            return Err("fetched_record_count must be >= 0".to_string());
        }
        if self.mapped_record_count < 0 as _ {
            return Err("mapped_record_count must be >= 0".to_string());
        }
        if self.profile_filtered_record_count < 0 as _ {
            return Err("profile_filtered_record_count must be >= 0".to_string());
        }
        if self.exact_duplicate_record_count < 0 as _ {
            return Err("exact_duplicate_record_count must be >= 0".to_string());
        }
        if self.unique_provider_product_count < 0 as _ {
            return Err("unique_provider_product_count must be >= 0".to_string());
        }
        if self.exact_matched_count < 0 as _ {
            return Err("exact_matched_count must be >= 0".to_string());
        }
        if self.returned_count < 0 as _ {
            return Err("returned_count must be >= 0".to_string());
        }
        if self.elapsed_ms < 0 as _ {
            return Err("elapsed_ms must be >= 0".to_string());
        }
        if self.mapped_record_count > self.fetched_record_count {
            return Err("mapped_record_count must not exceed fetched_record_count".to_string());
        }
        if self
            .unique_provider_product_count
            .checked_add(self.exact_duplicate_record_count)
            != Some(self.mapped_record_count)
        {
            return Err(
                "mapped_record_count must equal unique_provider_product_count plus exact_duplicate_record_count".to_string(),
            );
        }
        if self.returned_count > self.unique_provider_product_count {
            return Err("returned_count must not exceed unique_provider_product_count".to_string());
        }
        if self.exact_matched_count > self.unique_provider_product_count {
            return Err(
                "exact_matched_count must not exceed unique_provider_product_count".to_string(),
            );
        }
        if self.returned_count > self.exact_matched_count {
            return Err("returned_count must not exceed exact_matched_count".to_string());
        }
        if self
            .matched_count
            .is_some_and(|matched_count| self.returned_count > matched_count)
        {
            return Err("returned_count must not exceed matched_count".to_string());
        }
        if !self.working_set_satisfied {
            return Err(
                "working_set_satisfied must confirm successful bounded completion".to_string(),
            );
        }
        Ok(())
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct CatalogSearchResponse {
    pub collection: CatalogCollectionDescriptor,
    #[serde(default)]
    pub products: Vec<ProviderProduct>,
    pub stats: CatalogSearchStats,
    #[serde(default)]
    pub next_cursor: Option<String>,
    #[serde(default)]
    pub item_errors: Vec<ContractError>,
}

impl CatalogSearchResponse {
    pub fn validate(&self) -> Result<(), String> {
        self.collection
            .validate()
            .map_err(|error| format!("{}.{}", "collection", error))?;
        for (index, value) in self.products.iter().enumerate() {
            let value_path = format!("{}[{}]", "products", index);
            value
                .validate()
                .map_err(|error| format!("{}.{}", value_path, error))?;
        }
        self.stats
            .validate()
            .map_err(|error| format!("{}.{}", "stats", error))?;
        if let Some(value) = &self.next_cursor {
            if value.chars().count() < 1 {
                return Err("next_cursor is too short".to_string());
            }
        }
        for (index, value) in self.item_errors.iter().enumerate() {
            let value_path = format!("{}[{}]", "item_errors", index);
            value
                .validate()
                .map_err(|error| format!("{}.{}", value_path, error))?;
        }
        if self
            .stats
            .mapped_record_count
            .checked_add(self.stats.profile_filtered_record_count)
            .and_then(|count| count.checked_add(self.item_errors.len() as u64))
            != Some(self.stats.fetched_record_count)
        {
            return Err(
                "fetched_record_count must equal mapped_record_count plus profile_filtered_record_count plus item_errors length"
                    .to_string(),
            );
        }
        if self.stats.returned_count != self.products.len() as u64 {
            return Err("returned_count must equal products length".to_string());
        }
        if self.stats.truncated != self.next_cursor.is_some() {
            return Err("truncated must match next_cursor presence".to_string());
        }
        if self
            .products
            .iter()
            .any(|product| product.provider_id != self.collection.provider_id)
        {
            return Err("product provider IDs must match the response collection".to_string());
        }
        let product_ids: HashSet<&str> = self
            .products
            .iter()
            .map(|product| product.product_id.as_str())
            .collect();
        if product_ids.len() != self.products.len() {
            return Err("product IDs must be unique within one response page".to_string());
        }
        Ok(())
    }
}

