#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct FrozenSearchStats {
    #[serde(default)]
    pub matched_count: Option<u64>,
    #[serde(default)]
    pub fetched_record_count: Option<u64>,
    #[serde(default)]
    pub mapped_record_count: Option<u64>,
    pub provider_returned_count: u64,
    pub frozen_candidate_count: u64,
    pub truncated: bool,
    pub source: String,
    #[serde(default)]
    pub source_attempts: Vec<FrozenSearchSourceAttempt>,
}

impl FrozenSearchStats {
    pub fn validate(&self) -> Result<(), String> {
        if let Some(value) = &self.matched_count {
            if *value < 0 as _ {
                return Err("matched_count must be >= 0".to_string());
            }
        }
        if let Some(value) = &self.fetched_record_count {
            if *value < 0 as _ {
                return Err("fetched_record_count must be >= 0".to_string());
            }
        }
        if let Some(value) = &self.mapped_record_count {
            if *value < 0 as _ {
                return Err("mapped_record_count must be >= 0".to_string());
            }
        }
        if self.provider_returned_count < 0 as _ {
            return Err("provider_returned_count must be >= 0".to_string());
        }
        if self.frozen_candidate_count < 0 as _ {
            return Err("frozen_candidate_count must be >= 0".to_string());
        }
        if self.source.chars().count() < 1 {
            return Err("source is too short".to_string());
        }
        if !["ASF", "ASF_BATCH", "ASF_CMR", "TYPED_CATALOG"].contains(&self.source.as_str()) {
            return Err("source must be one of the declared values".to_string());
        }
        if self.source_attempts.len() > 8 {
            return Err("source_attempts must contain at most 8 items".to_string());
        }
        for (index, value) in self.source_attempts.iter().enumerate() {
            let value_path = format!("{}[{}]", "source_attempts", index);
            value
                .validate()
                .map_err(|error| format!("{}.{}", value_path, error))?;
        }
        if let Some((final_attempt, previous_attempts)) = self.source_attempts.split_last() {
            if previous_attempts.iter().any(|attempt| {
                attempt.outcome != FrozenSearchSourceAttemptOutcome::Fallback
                    || attempt.fallback_reason.is_none()
            }) {
                return Err(
                    "source attempts before the final success must be bounded fallbacks"
                        .to_string(),
                );
            }
            if final_attempt.outcome != FrozenSearchSourceAttemptOutcome::Succeeded
                || final_attempt.fallback_reason.is_some()
            {
                return Err(
                    "source attempts must end in one success without a fallback reason".to_string(),
                );
            }
        }
        Ok(())
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct FrozenSearchBatch {
    pub schema_version: u64,
    pub batch_id: String,
    pub provider_id: String,
    pub created_at: String,
    pub aoi_name: String,
    #[serde(default)]
    pub aoi_geojson: Option<Map<String, Value>>,
    #[serde(default)]
    pub query: Map<String, Value>,
    #[serde(default)]
    pub search_stats: Option<FrozenSearchStats>,
    pub candidates: Vec<SnapshotItem>,
}

impl FrozenSearchBatch {
    pub fn validate(&self) -> Result<(), String> {
        if self.schema_version < 1 as _ {
            return Err("schema_version must be >= 1".to_string());
        }
        if self.batch_id.chars().count() < 1 {
            return Err("batch_id is too short".to_string());
        }
        if self.provider_id.chars().count() < 1 {
            return Err("provider_id is too short".to_string());
        }
        if self.aoi_name.chars().count() < 1 {
            return Err("aoi_name is too short".to_string());
        }
        validate_debug_context(&self.query)?;
        if let Some(value) = &self.search_stats {
            value
                .validate()
                .map_err(|error| format!("{}.{}", "search_stats", error))?;
        }
        for (index, value) in self.candidates.iter().enumerate() {
            let value_path = format!("{}[{}]", "candidates", index);
            value
                .validate()
                .map_err(|error| format!("{}.{}", value_path, error))?;
        }
        if let Some(aoi_geojson) = &self.aoi_geojson {
            let geometry_type = aoi_geojson
                .get("type")
                .and_then(Value::as_str)
                .unwrap_or("");
            if !matches!(
                geometry_type,
                "Polygon" | "MultiPolygon" | "Feature" | "FeatureCollection" | "GeometryCollection"
            ) {
                return Err("aoi_geojson must contain real polygon topology".to_string());
            }
        }
        let candidate_ids: HashSet<&str> = self
            .candidates
            .iter()
            .map(|item| item.item_id.as_str())
            .collect();
        if candidate_ids.len() != self.candidates.len() {
            return Err("candidate item IDs must be unique".to_string());
        }
        if self
            .candidates
            .iter()
            .any(|item| item.provider_id != self.provider_id)
        {
            return Err("candidate provider IDs must match the batch provider".to_string());
        }
        if let Some(search_stats) = &self.search_stats {
            if let Some(final_attempt) = search_stats.source_attempts.last() {
                if final_attempt.provider_id != self.provider_id {
                    return Err(
                        "final source attempt provider must match the batch provider".to_string(),
                    );
                }
            }
        }
        Ok(())
    }
}

